751			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
752			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
753		}
754		res1, err := r.Preview(ops)
755		if err != nil {
756			t.Fatal(err)
757		}
