759		res1.Submittable = true
760		res1.CargoChanges[0].CargoID = "HACKED"
761		res1.Compartments[0].After.UsedWeight = 9999
762		res1.Compartments[0].After.Cargo[0].ID = "HACKED"
763		res1.Rejections[0].CompartmentID = "HACKED"
764		res1.Rejections[0].OffendingCargo[0] = "HACKED"
