772			t.Fatal("新预览不应被污染，仍应不可提交")
773		}
774		if res2.CargoChanges[0].CargoID == "HACKED" ||
775			res2.Compartments[0].After.UsedWeight == 9999 ||
776			res2.Compartments[0].After.Cargo[0].ID == "HACKED" ||
777			res2.Rejections[0].CompartmentID == "HACKED" ||
