			comp string
			kind ErrorKind
		}{x.CompartmentID, x.Kind}
	}
	want := []struct {
		comp string
		kind ErrorKind
	}{
		{"C1", ErrOverweight},
		{"C1", ErrMixedLoading},
		{"C2", ErrOverweight},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("拒绝原因次序错误: %+v", got)
