	// 登记处本身也未受影响。
	cv, _ := r.Cargo("G1")
	if cv.Loaded {
		t.Fatalf("货物仍应未装载: %+v", cv)
	}
}

func TestPreviewDoesNotTouchAdjustmentRecords(t *testing.T) {
